function renderBFinalResult(a,earned){
  document.getElementById('bFinalResultPoints').textContent=`${a.rate}%`;
  document.getElementById('bFinalResultRaw').textContent=`${a.correct} / 20 正解`;
  document.getElementById('bFinalResultMessage').textContent=a.rate>=80?`かなり安定しています。時間配分を保ったまま精度を維持しましょう。+${earned} XP`:a.rate>=60?`練習上の目安には届いています。誤答分野を潰して余裕を作りましょう。+${earned} XP`:a.rate>=45?`あと少しです。誤答を「トレース」「読解」「判断」に分けて復習しましょう。+${earned} XP`:`学習モードへ戻り、途中状態を書き出す練習から積み直すのがおすすめです。+${earned} XP`;
  document.getElementById('bFinalStatCorrect').textContent=a.correct;
  document.getElementById('bFinalStatWrong').textContent=20-a.correct-a.blank;
  document.getElementById('bFinalStatBlank').textContent=a.blank;
  document.getElementById('bFinalStatTime').textContent=bMockFormatTime(a.seconds);
  document.getElementById('bFinalAlgoScore').textContent=`${a.algoCorrect} / 16`;
  document.getElementById('bFinalSecScore').textContent=`${a.secCorrect} / 4`;
  renderBFinalDiagnosis(a);

  const formats=[...new Set(a.details.map(d=>d.format))];
  document.getElementById('bFinalFormatBreakdown').innerHTML=formats.map(f=>{
    const rows=a.details.filter(d=>d.format===f),n=rows.filter(d=>d.ok).length,pct=Math.round(n/rows.length*100);
    return `<div class="bfinal-format-row"><div class="bfinal-format-label">${escapeHtml(f)}</div><div class="bfinal-format-bar"><div class="bfinal-format-fill" style="width:${pct}%"></div></div><div class="bfinal-format-score">${n}/${rows.length}</div></div>`;
  }).join('');

  document.getElementById('bFinalReviewList').innerHTML=a.details.map((d,i)=>{
    const mk=bFinalMistakeKey(d),ms=profile.bFinalMistakeStats?.[mk],reason=ms?.lastReason||'';const meta=bFinalReviewReasonMeta(reason,d);
    return `<div class="bfinal-review-item ${d.ok?'correct':'wrong'}"><div class="bfinal-review-top"><b>Q${i+1} ${escapeHtml(d.title)}</b><span>${d.kind==='security'?'🛡️ '+escapeHtml(d.domain||'セキュリティ'):'💻 '+escapeHtml(d.domain||'擬似言語')+' / '+escapeHtml(d.format)} / ${d.ok?'✓ 正解':'✕ 要復習'}</span></div><div class="bfinal-review-q">${escapeHtml(d.q)}</div><div class="bfinal-review-a">あなたの回答：<b>${d.selected===null?'未回答':escapeHtml(d.selected)}</b><br>正解：<b>${escapeHtml(d.correct)}</b></div><div class="bfinal-review-e">${escapeHtml(d.explain)}</div>${d.ok?'':`<div class="bfinal-review-reason"><div class="bfinal-review-reason-title">なぜ崩れましたか？</div><div class="bfinal-review-reason-chips">${['トレースミス','コード理解','読み違い','知識不足','時間不足'].map(r=>`<button class="bfinal-review-reason-chip ${reason===r?'picked':''}" data-bfreason="${r}" data-bfkey="${escapeHtml(mk)}">${r}</button>`).join('')}</div></div><div class="bfinal-review-action" data-bfaction="${escapeHtml(mk)}"><b>${escapeHtml(meta[0])}</b>${escapeHtml(meta[1])}</div><button class="bfinal-review-study smart" data-bfinalstudy="${escapeHtml(d.studyMode)}" data-bfinalsource="${escapeHtml(d.sourceId)}" data-bfinaldomain="${escapeHtml(d.domain||'')}">${escapeHtml(meta[0])} →</button>`}</div>`;
  }).join('');
  document.querySelectorAll('[data-bfreason]').forEach(btn=>btn.onclick=()=>{
    const key=btn.dataset.bfkey,reason=btn.dataset.bfreason,st=profile.bFinalMistakeStats[key];if(!st)return;
    if(st.lastReason&&st.reasons?.[st.lastReason])st.reasons[st.lastReason]=Math.max(0,st.reasons[st.lastReason]-1);
    st.lastReason=reason;st.reasons=st.reasons||{};st.reasons[reason]=(st.reasons[reason]||0)+1;st.last=localDateISO(0);saveProfile();renderBFinalResult(a,0);
  });
  document.querySelectorAll('[data-bfinalstudy]').forEach(btn=>btn.onclick=()=>{
    document.getElementById('bFinalResult')?.classList.remove('show');
    const target=bFinalRemediationTarget(btn.dataset.bfinalstudy,btn.dataset.bfinalsource,btn.dataset.bfinaldomain);
    if(target.mode==='security'){
      setBMode('security');startSecurityScenario(target.id);
    }else if(target.mode==='trace'){
      setBMode('trace');startBExercise(target.id);
    }else if(target.mode==='compound'){
      setBMode('mock');startCompoundChallenge();
    }else{
      setBMode('mock');showBMockMenu();
    }
  });
}

sourceExtracts.launch:
function launchSubjectBRecommendation(rec){
  if(!rec)return;
  showScreen('trace');
  if(rec.mode==='trace'){setBMode('trace');if(rec.id)startBExercise(rec.id);}
  else if(rec.mode==='security'){setBMode('security');if(rec.id)startSecurityScenario(rec.id);}
  else if(rec.mode==='compound'){setBMode('mock');startCompoundChallenge();}
  else if(rec.mode==='securityMock'){setBMode('security');startSecurityMock();}
  else if(rec.mode==='miniMock'){setBMode('mock');startBMiniMock();}
  else if(rec.mode==='final'){setBMode('final');}
}

