function(){
  const rec=_subjectBHubRecommendationV227();
  const days=examDaysRemaining();
  const finalAllowed=!(days!=null&&days>=0&&days<=3);
  if(!finalAllowed)return rec;
  if(!rec||rec.mode!=='miniMock'||rec.title!=='アルゴリズム ミニ模試で準備')return rec;
  const context=subjectBAlgorithmDomainContextV227();
  if(!context)return rec;
  let marker=profile.subjectBAlgorithmDomainV227;
  if(!marker||marker.firstFinalKey!==context.firstFinalKey){
    marker=subjectBAlgorithmDomainMarkerV227(context,false);
    profile.subjectBAlgorithmDomainV227=marker;
    saveProfile();
  }
  if(marker.completed)return rec;
  if(marker.domain!==context.target.domain||marker.targetId!==context.target.id){
    marker=subjectBAlgorithmDomainMarkerV227(context,false);
    profile.subjectBAlgorithmDomainV227=marker;
    saveProfile();
  }
  return subjectBAlgorithmDomainTraceRecV227(marker);
}

sourceExtracts.mark:
function subjectBMarkAlgorithmDomainTraceCompleteV227(traceId){
  const context=subjectBAlgorithmDomainContextV227();
  const marker=profile.subjectBAlgorithmDomainV227;
  if(marker&&marker.firstFinalKey===subjectBFirstFinalKeyV222(profile.bFinalHistory?.[0])&&!marker.completed&&marker.targetId===traceId){
    marker.completed=true;
    marker.completedAt=localDateISO(0);
    return true;
  }
  if(context&&context.target.id===traceId){
    profile.subjectBAlgorithmDomainV227=subjectBAlgorithmDomainMarkerV227(context,true);
    profile.subjectBAlgorithmDomainV227.completedAt=localDateISO(0);
    return true;
  }
  return false;
}
